{
  "interpretation": {
    "name": "TightenLine1WithSharedNutrunnerWithoutRecording",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Tighten the fasteners of variant F25 at station st1 of line 1 with the shared nutrunner NR7 and evaluate the result, without recording it.",
    "constraints": [
      "NR7 must be reserved exclusively and the lease renewed before every physical use",
      "NR7 must be at station st1 before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program for variant F25",
      "transport-tool must be delegated to agvexecutor",
      "The tightening result must be evaluated against its program",
      "NR7 must be returned to the crib and released after use, so that other lines can use it",
      "The operator explicitly asked not to record the result, so record-tightening is left out. Quality policy E5 requires recording for traceability, which the validator may flag."
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": ["record-tightening"]
  },
  "recipe": {
    "name": "line1-tighten-nr7-no-record",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver-tool",
        "next": "tighten-and-evaluate",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten-and-evaluate",
        "next": "return-tool",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten",
            "service": "tighten-fasteners",
            "next": ["evaluate"],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten", "program"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": "free-tool",
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          }
        ]
      },
      {
        "name": "free-tool",
        "next": null,
        "steps": [
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
